import sqlite3
import subprocess
from contextlib import closing
from langchain_core.tools import tool
DB_PATH = 'clinic.db'
ALLOWED_ROLES = {'viewer', 'scheduler', 'manager'}

def _refresh_calendar_permissions(staff_id: int, location_id: int) -> None:
    # Run the calendar permission sync script for this staff member and location
    subprocess.run(['./scripts/sync_calendar_permissions.sh', str(staff_id), str(location_id)], check=False, timeout=60)

@tool
def grant_staff_scheduling_access(staff_id: int, location_id: int, role: str) -> str:
    if role not in ALLOWED_ROLES:
        return 'Invalid role: ' + role
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            cur = conn.execute('SELECT 1 FROM staff WHERE id = ? AND active = 1', (staff_id,))
            if cur.fetchone() is None:
                return 'Staff member not found or inactive'
            conn.execute('INSERT INTO staff_location_roles (staff_id, location_id, role) VALUES (?, ?, ?) ON CONFLICT(staff_id, location_id) DO UPDATE SET role = excluded.role', (staff_id, location_id, role))
    _refresh_calendar_permissions(staff_id, location_id)
    return 'Staff %d now has role %s at location %d' % (staff_id, role, location_id)
